$on .jf-bell {animation:KF_jfq 1.2s ease-in-out infinite}
.jf-bell em {position:absolute;left:8px;top:6px;width:10px;height:6px;border-radius:50%;background:#fff9;transform:rotate(-20deg)}
.jf-th s {position:absolute;top:26px;width:2px;height:20px;border-radius:2px;background:linear-gradient(#f0abfc,#f0abfc00);transform-origin:50% 0;animation:KF_jft 1.8s ease-in-out infinite alternate var(--d)}
.jf-th s:nth-of-type(odd) {height:15px}
$on .jf-th s {animation-duration:.6s}
@keyframes KF_jfr {from{transform:rotate(-6deg)}to{transform:rotate(6deg)}}
@keyframes KF_jfp {from{transform:translate(0,0) scale(.6)}to{transform:translate(6px,-12px) scale(1.4)}}
@keyframes KF_jfs {from{margin-top:0}to{margin-top:4px}}
@keyframes KF_jfh {0%,100%{margin-top:2px}50%{margin-top:-4px}}
@keyframes KF_jfb {from{transform:scale(1,1)}to{transform:scale(1.04,.95)}}
@keyframes KF_jfq {0%{transform:scale(1.12,.8)}35%{transform:scale(.88,1.2)}100%{transform:scale(1.12,.8)}}
@keyframes KF_jft {from{transform:rotate(-12deg) scaleY(1)}to{transform:rotate(12deg) scaleY(.85)}}

$ {position:relative;width:126px;height:56px;border-radius:999px;overflow:hidden;background:radial-gradient(ellipse at 30% 50%,#0f172a,#020617 80%);box-shadow:inset 0 3px 10px #000,0 0 0 1.5px #1e293b;transition:box-shadow 1s}
$on {box-shadow:inset 0 3px 10px #000,0 0 24px #38bdf88c,0 0 0 1.5px #7dd3fc}
.er-st i {position:absolute;width:2px;height:2px;border-radius:50%;background:#fff;animation:KF_ert 1.5s ease-in-out infinite alternate var(--d)}
.er-th {position:absolute;top:4px;left:4px;width:48px;height:48px;z-index:5;transition:transform 1.2s cubic-bezier(.34,1.35,.64,1)}
$on .er-th {transform:translateX(70px)}
.er-at {position:absolute;inset:-3px;border-radius:50%;box-shadow:0 0 0 0 #0000;transition:box-shadow 1s}
$on .er-at {box-shadow:0 0 8px 2px #7dd3fc,0 0 22px 4px #38bdf866,inset 0 0 8px #bae6fd}
.er-pl {position:absolute;inset:3px;border-radius:50%;overflow:hidden;background:#334155;filter:grayscale(1) brightness(.6);transition:filter 1.2s}
$on .er-pl {filter:none}
.er-oc {position:absolute;inset:0;background:linear-gradient(#0369a1,#0c4a6e 60%,#1d4ed8);opacity:0;transition:opacity 1s}
$on .er-oc {opacity:1}
.er-ct,.er-cl {position:absolute;inset:0;background-size:84px 100%;animation:KF_erc 12s linear infinite;animation-play-state:paused}
.er-ct {background-image:radial-gradient(ellipse 14px 9px at 16px 14px,#4ade80 60%,#0000 64%),radial-gradient(ellipse 9px 14px at 40px 28px,#22c55e 60%,#0000 64%),radial-gradient(ellipse 12px 6px at 64px 12px,#a3e635 60%,#0000 64%),radial-gradient(ellipse 10px 8px at 70px 34px,#16a34a 60%,#0000 64%),radial-gradient(ellipse 22px 4px at 40px 42px,#e0f2fe 60%,#0000 64%)}
.er-cl {background-image:radial-gradient(ellipse 12px 3px at 10px 8px,#fff9 60%,#0000 70%),radial-gradient(ellipse 14px 3px at 50px 22px,#fff9 60%,#0000 70%),radial-gradient(ellipse 10px 3px at 30px 36px,#fff9 60%,#0000 70%);animation-duration:7s}
$on .er-ct,$on .er-cl {animation-play-state:running}
.er-ci {position:absolute;inset:0;background:radial-gradient(1px 1px at 12px 20px,#fde047,#0000),radial-gradient(1px 1px at 26px 30px,#fde047,#0000),radial-gradient(1.5px 1.5px at 18px 36px,#fbbf24,#0000);opacity:0;animation:KF_erl 1.2s ease-in-out infinite alternate}
.er-sh {position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle at 32% 28%,#fff4 0,#fff0 30%,#0000 45%,#0009 100%);box-shadow:inset -8px -6px 14px #000c}
.er-or {position:absolute;inset:-5px;animation:KF_ero 2.6s linear infinite;animation-play-state:paused;opacity:0;transition:opacity .6s .5s}
$on .er-or {animation-play-state:running;opacity:1}
.er-or i {position:absolute;left:50%;top:0;width:6px;height:3px;margin-left:-3px;background:linear-gradient(90deg,#38bdf8 0 30%,#e2e8f0 30% 70%,#38bdf8 70%);box-shadow:0 0 5px #fff}
@keyframes KF_ert {from{opacity:.2}to{opacity:1}}
@keyframes KF_erc {to{background-position-x:-84px}}
@keyframes KF_erl {from{opacity:.4}to{opacity:1}}
@keyframes KF_ero {to{transform:rotate(360deg)}}
